\begin{eqnarray}
{\cal L}_{\mu \to i}(a_\mu, z_\mu)=- z_\mu a_\mu+\sum_{j \ne i} 
\left \{
\mathop{\rm min}_{x_j}\left \{
{\cal L}_{j \to \mu} (x_j)+\Phi_{\mu j} a_\mu x_j \right \} \right \}, 
\label{Hstep}
\end{eqnarray}
which offers 
\begin{eqnarray}
B_{\mu \to i}&=&\sum_{j \ne i} \frac{\Phi_{\mu j}^2}{A_{j \to \mu}} g^{\prime \prime}(H_{j \to \mu}), \label{HstepB} \\
K_{\mu \to i}&=&\sum_{j \ne i} \frac{\Phi_{\mu j}}{A_{j \to \mu}}g^{\prime}(H_{j \to \mu}).  \label{HstepK}
\end{eqnarray}
